'use strict';
let academyWorker=null,academyFiles=[],academyReport=null;
function showView(view){releaseInputs();for(const [key,id]of [['home','homeView'],['play','matchView'],['academy','academyView']])$(id).hidden=key!==view;for(const [key,id]of [['home','tabHome'],['play','tabPlay'],['academy','tabAcademy']])$(id).classList.toggle('active',key===view);$('tabReplay').classList.remove('active');if(view==='play'){$('gameCanvas').focus();renderer.render();}else if(started&&!paused&&!peerConnected&&!replay)togglePause();}
$('tabHome').onclick=()=>showView('home');$('tabPlay').onclick=()=>showView('play');$('tabAcademy').onclick=$('quickAcademy').onclick=()=>showView('academy');$('tabReplay').onclick=()=>{showView('play');$('replayFile').click();};
function quickPlay(mode){if(replay)closeReplay();if(peerConnected)disconnect();$('mode').value=mode;showView('play');resetMatch(true);}
$('heroPlay').onclick=$('quickMatch').onclick=()=>quickPlay('bot');$('quickSquad').onclick=()=>quickPlay('4v4');$('quickOnline').onclick=()=>{showView('play');openDialog('networkDialog');};
function setModel(model){FuckballAI.validateModel(model);aiModel=model;FuckballAI.reset(aiModel);$('modelName').textContent=model.name||'Geïmporteerd model';const metrics=model.source_metrics||{};const accuracy=metrics.direction_accuracy??metrics.dir_accuracy;$('modelAccuracy').textContent=Number.isFinite(accuracy)?(accuracy*100).toFixed(1)+'%':'—';$('modelSamples').textContent=Number(model.training?.train_samples||model.training?.samples||model.training?.train_stats?.samples||0).toLocaleString('nl-NL');$('modelDescription').textContent=model.input_columns.length+' spelkenmerken · '+model.b1.length+' neuronen · kick F1 '+(Number(metrics.kick_f1)||0).toFixed(2)+' · '+(model.source_kind||'geïmporteerd');$('exportModel').disabled=false;}
fetch('ai/trained-model.json').then(r=>{if(!r.ok)throw Error('Model laden mislukt');return r.json();}).then(setModel).catch(e=>{$('modelName').textContent='Tactische AI beschikbaar';$('modelDescription').textContent=e.message;$('exportModel').disabled=true;});
$('aiMode').onchange=()=>{if($('aiMode').value!=='tactical'&&!aiModel){$('aiMode').value='tactical';notify('Laad of train eerst een model.');}FuckballAI.reset(aiModel);};
$('importModel').onclick=()=>$('modelFile').click();$('modelFile').onchange=async e=>{try{const f=e.target.files[0];if(!f)return;if(f.size>16*1024*1024)throw Error('Model maximaal 16 MB.');setModel(JSON.parse(await f.text()));notify('Model geladen. Kies Neuraal of Hybride om het te testen.');}catch(err){notify(err.message);}e.target.value='';};
$('exportModel').onclick=()=>{if(aiModel)saveBlob(JSON.stringify(aiModel),safeName(aiModel.name)+'.json','application/json');};
$('academyUpload').onclick=()=>$('academyFiles').click();$('academyFiles').onchange=e=>{academyFiles=Array.from(e.target.files||[]);$('datasetSummary').textContent=academyFiles.length+' replays · '+(academyFiles.reduce((s,f)=>s+f.size,0)/1024/1024).toFixed(1)+' MB';$('trainModel').disabled=academyFiles.length<3||!!academyWorker;$('analyzeReplays').disabled=!academyFiles.length||!!academyWorker;};
function taskState(busy){$('cancelTraining').disabled=!busy;$('academyUpload').disabled=busy;$('analyzeReplays').disabled=busy||!academyFiles.length;$('trainModel').disabled=busy||academyFiles.length<3;}
async function startAcademy(train){if(academyWorker)return;try{if(!academyFiles.length)throw Error('Kies eerst een replay.');if(academyFiles.length>20||academyFiles.some(f=>f.size>32*1024*1024)||academyFiles.reduce((s,f)=>s+f.size,0)>128*1024*1024)throw Error('Maximaal 20 replays, 32 MB per replay en 128 MB totaal.');taskState(true);$('academyState').textContent=train?'TRAINING':'ANALYSE';$('trainingStatus').textContent='Bestanden lezen…';$('trainingProgress').value=0;const worker=new Worker('ai/trainer-worker.js');academyWorker=worker;worker.onerror=e=>finishTask(e.message||'Worker kon niet starten.');worker.onmessage=({data})=>{if(data.type==='progress'){$('trainingProgress').value=data.percent;$('trainingStatus').textContent=data.text;}else if(data.type==='error')finishTask(data.message);else if(data.type==='done'){academyReport=data.report;$('analysisResults').replaceChildren();for(const r of data.report.replays){const el=document.createElement('div');el.className='analysis-row';const title=document.createElement('b');title.textContent=r.name+' · '+r.map;const detail=document.createElement('span');detail.textContent=fmt(r.duration_seconds)+' · '+r.players+' spelers · '+r.redGoals+'–'+r.blueGoals+' · '+r.kicks+' kicks · '+r.split;el.append(title,detail);$('analysisResults').append(el);}if(data.model){setModel(data.model);$('aiMode').value='tactical';}$('downloadAnalysis').disabled=false;$('trainingProgress').value=100;finishTask(null,data.model?'Model getraind en geladen als kandidaat. Kies Neuraal om het te evalueren.':'Replay-analyse voltooid.');}};const files=await Promise.all(academyFiles.map(async f=>({name:f.name,bytes:await f.arrayBuffer()})));if(academyWorker===worker)worker.postMessage({files,train},files.map(f=>f.bytes));}catch(e){finishTask(e.message);}}
function finishTask(error,message){academyWorker?.terminate();academyWorker=null;taskState(false);$('academyState').textContent=error?'FOUT':'KLAAR';$('trainingStatus').textContent=error||message||'Taak gestopt.';}
$('analyzeReplays').onclick=()=>startAcademy(false);$('trainModel').onclick=()=>startAcademy(true);$('cancelTraining').onclick=()=>finishTask(null,'Taak gestopt. Je huidige model blijft beschikbaar.');$('downloadAnalysis').onclick=()=>{if(academyReport)saveBlob(JSON.stringify(academyReport,null,2),'fuckball-replay-analyse.json','application/json');};
showView('home');taskState(false);
